scripts.script:
if (!Macros.checkStance(actor, args)) return;

// 获取AE模板
const eff = thisItem.effects.getName("侵杀").toObject();
delete eff._id;
eff.origin = thisItem.uuid;

await game.xjzl.api.effects.addEffect(actor, eff);
ui.notifications.info("格挡成功，获得 [侵杀]！");

if (args.isHit) {
    // 骑马状态无法自动判断，只判断基础条件
    if (!args.target.system.martial.stanceActive) {
        const eff = thisItem.effects.getName("刀势").toObject();
        delete eff._id;
        eff.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(actor, eff);
    } else {
        ui.notifications.info("目标有架招。若你处于 [骑马] 状态，请手动添加 [刀势] 层数。");
    }
}

if (args.isBroken) {
    await game.xjzl.api.effects.removeEffect(actor, "daoshi", 1);
    ui.notifications.info("击破架招！已移除1层刀势。请手动处理移动与连击。");
}

const qinsha = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "qinsha");
if (qinsha) {
    const shanie = actor.system.resources.shanie || 0;
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "锋行千杀" },
        content: `<p>当前持有 [侵杀]，杀孽值为 <b>${shanie}</b>。</p><p>是否消耗 [侵杀] 以增加等额伤害？</p>`,
        yes: { label: "消耗 (+杀孽)", icon: "fas fa-skull" },
        no: { label: "不消耗", icon: "fas fa-times" }
    });

    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "qinsha", 1);
        args.flags.damageResult.damage += shanie;
        args.flags.damageResult.breakdown += `\n+ 杀孽加成: ${shanie}`;
        ui.notifications.info("已消耗侵杀，杀意沸腾！");
    }
}

if (args.isBroken) {
    await game.xjzl.api.effects.toggleStatus(args.target, 'blind', true);
    ui.notifications.info(`${args.target.name} 双目被黄沙迷障！`);
}

const hp = actor.system.resources.hp.value;
const maxHp = actor.system.resources.hp.max;
const pct = hp / maxHp;
let bonus = 0;
if (pct <= 0.5) bonus += 10;
if (pct <= 0.1) bonus += 10;
if (bonus > 0) {
    args.output.damage += bonus;
    args.output.bonusDesc.push(`绝境加伤 +${bonus}`);
}

const hp = actor.system.resources.hp.value;
const maxHp = actor.system.resources.hp.max;
const pct = hp / maxHp;
let bonus = 0;
if (pct <= 0.5) bonus += 10;
if (pct <= 0.1) bonus += 10;
if (bonus > 0) {
    const msg = "<div class='xjzl-chat-card' style='margin-left: 6px;'><div style='border-left: 3px solid #e67e22; background: rgba(230, 126, 34, 0.1); padding: 5px 8px;'><div style='font-weight:bold; color:#d35400;'><i class='fas fa-fire'></i> 绝境爆发</div><div style='font-size:0.9em; color:#555; margin-top:3px;'>触发绝境加伤，招式额外造成 <span style='color:#e67e22; font-weight:bold;'>" + bonus + "</span> 点伤害！</div></div></div>";
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

const eff = thisItem.effects.getName('刀浪').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
const lvl = Math.max(1, move.computedLevel || 1);
eff.duration = { rounds: 1 + (lvl - 1) };
await game.xjzl.api.effects.addEffect(actor, eff);

const confirm = await foundry.applications.api.DialogV2.prompt({
    window: { title: '破沙裂天 - 虚招压制' },
    content: '<p>看破对方虚招！请输入对方此次<b>虚招伤害</b>的面板数值：</p><input type="number" name="dmgVal" value="0" style="text-align:center;">',
    ok: {
        label: '确定',
        callback: (ev, btn) => parseInt(new FormData(btn.form).get('dmgVal')) || 0
    }
});
if (confirm) {
    args.flags.damageResult.damage += confirm;
    args.flags.damageResult.breakdown += `\n+ 压制虚招: ${confirm}`;
}

if (!args.target.system.martial?.stanceActive) {
    await args.target.applyDamage({ amount: 50, type: 'liushi', attacker: actor, isHit: true, ignoreDefense: true, ignoreBlock: true, ignoreStance: true });
    const msg = "<div class='xjzl-chat-card' style='margin-left: 6px;'><div style='border-left: 3px solid #c0392b; background: rgba(192, 57, 43, 0.1); padding: 5px 8px;'><div style='font-weight:bold; color:#8b0000;'><i class='fas fa-tint'></i> 卷沙葬海</div><div style='font-size:0.9em; color:#555; margin-top:3px;'><b>" + args.target.name + "</b> 未开启架招，被风沙侵入心肺，受到流失伤害！</div></div></div>";
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

const hp = actor.system.resources.hp.value;
const maxHp = actor.system.resources.hp.max;
if (hp / maxHp <= 0.1) {
    await game.xjzl.api.effects.addEffect(args.target, { id: 'fengzhao', duration: { rounds: 1 } });
    const msg2 = "<div class='xjzl-chat-card' style='margin-left: 6px;'><div style='border-left: 3px solid #2980b9; background: rgba(41, 128, 185, 0.1); padding: 5px 8px;'><div style='font-weight:bold; color:#154360;'><i class='fas fa-lock'></i> 绝境反击</div><div style='font-size:0.9em; color:#555; margin-top:3px;'><b>" + args.target.name + "</b> 受到强震，陷入<span style='color:red; font-weight:bold;'>封招</span>！</div></div></div>";
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg2 });
}

const hp = actor.system.resources.hp.value;
const maxHp = actor.system.resources.hp.max;
const pct = hp / maxHp;
let dmgBonus = 0;
let feintBonus = 0;
if (pct <= 0.5) { dmgBonus += 10; feintBonus += 1; }
if (pct <= 0.1) { dmgBonus += 10; feintBonus += 2; }
if (dmgBonus > 0) {
    args.output.damage += dmgBonus;
    args.output.feint += feintBonus;
    args.output.bonusDesc.push('刀浪绝境强化');
}

const hp = actor.system.resources.hp.value;
const maxHp = actor.system.resources.hp.max;
const pct = hp / maxHp;
if (pct <= 0.5) {
    const msg = "<div class='xjzl-chat-card' style='margin-left: 6px;'><div style='border-left: 3px solid #d35400; background: rgba(211, 84, 0, 0.1); padding: 5px 8px;'><div style='font-weight:bold; color:#c0392b;'><i class='fas fa-wind'></i> 绝境刀浪</div><div style='font-size:0.9em; color:#555; margin-top:3px;'>刀浪效果大幅增强！</div></div></div>";
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

const str = actor.system.stats.liliang.total;
if (str > 150) {
    const extra = Math.min(str - 150, 30);
    args.output.damage += extra;
    args.output.bonusDesc.push(`神力加伤 +${extra}`);
}

if (actor.system.martial?.stanceActive) {
    args.abort = true;
    args.abortReason = '无上形必须在无架招状态下施展！';
}

const eff = thisItem.effects.getName('无上形').toObject();
delete eff._id;
eff.origin = thisItem.uuid;
const lvl = Math.max(1, move.computedLevel || 1);
const dmgBonus = 10 + (lvl - 1) * 10;
eff.flags['xjzl-system'] = eff.flags['xjzl-system'] || {};
eff.flags['xjzl-system'].wushangxingDmg = dmgBonus;
await game.xjzl.api.effects.addEffect(actor, eff);

const eff = thisItem.effects.getName("癫狂").toObject();
delete eff._id;
eff.origin = thisItem.uuid;

const lvl = Math.max(1, move.computedLevel || 1);
eff.duration = { rounds: 1 + (lvl - 1) };

await game.xjzl.api.effects.addEffect(actor, eff);
ui.notifications.info("进入 [癫狂] 状态。请注意特殊状态替换规则。");

if (!args.target.system.martial?.stanceActive) {
    const bonus = thisEffect.getFlag('xjzl-system', 'wushangxingDmg') || 10;
    args.config.amount += bonus;
}

if (args.isHit && !args.target.system.martial?.stanceActive) {
    const bonus = thisEffect.getFlag('xjzl-system', 'wushangxingDmg') || 10;
    const stunData = { id: 'xuanyun', duration: { rounds: 1 } };
    await game.xjzl.api.effects.addEffect(actor, stunData);
    await game.xjzl.api.effects.addEffect(args.target, stunData);
    const msg = "<div class='xjzl-chat-card' style='margin-left: 6px;'><div style='border-left: 3px solid #f39c12; background: rgba(243, 156, 18, 0.1); padding: 5px 8px;'><div style='font-weight:bold; color:#d35400;'><i class='fas fa-bolt'></i> 无上形 爆发</div><div style='font-size:0.9em; color:#555; margin-top:3px;'>无上形反噬！招式附加了 <span style='color:red; font-weight:bold;'>" + bonus + "</span> 点伤害，且双方陷入<span style='color:red; font-weight:bold;'>眩晕</span>！</div></div></div>";
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
    if (game.combat && game.combat.combatant?.actorId === actor.id) {
        await game.combat.nextTurn();
    }
    await game.xjzl.api.effects.removeEffect(actor, "wushangxing", 1);
}

const eff = thisItem.effects.getName("不动").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
await game.xjzl.api.effects.addEffect(actor, eff);
ChatMessage.create({
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #f1c40f; background:rgba(241,196,15,0.1);"><b>不动明王：</b>免疫点穴、击退、击飞、击倒、错骨。请在遇袭时手动判定免疫。</div></div>`
});

if (args.isHit && !args.target.system.martial.stanceActive) {
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #e74c3c; background:rgba(231,76,60,0.1);"><b>击飞：</b>将 ${args.target.name} 击飞 1 米并倒地！</div></div>`
    });
    await game.xjzl.api.effects.addEffect(args.target, "prone");
}

if (args.isBroken) {
    const fofa = args.target.system.arts.fofa?.total || 0;
    const daofa = args.target.system.arts.daofa?.total || 0;
    const lvl = Math.max(1, move.computedLevel || 1);

    if (fofa > 0 || daofa > 0) {
        await Macros.requestSave({
            target: args.target,
            attacker: actor,
            type: "dingli",
            dc: 13 + (lvl - 1) * 2,
            label: "抵抗眩晕 (佛/道法)",
            onFail: { id: "xuanyun", duration: { rounds: 1 } }
        });
    } else {
        await game.xjzl.api.effects.addEffect(args.target, { id: "xuanyun", duration: { rounds: 1 } });
    }
}

const maxHp = S.resources.hp.max;
const lvl = Math.max(1, move.computedLevel || 1);
args.output.damage = Math.floor(maxHp * (0.1 + (lvl - 1) * 0.1));

ChatMessage.create({
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #2ecc71; background:rgba(46,204,113,0.1);"><b>三吸二吐：</b>请手动移除身上一个负面状态。</div></div>`
});

const eff = thisItem.effects.getName("避凶").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
const lvl = Math.max(1, move.computedLevel || 1);
const bonus = 1 + (lvl - 1);
eff.changes[0].value = String(bonus);
eff.changes[1].value = String(bonus);
await game.xjzl.api.effects.addEffect(actor, eff);
ChatMessage.create({
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #9b59b6; background:rgba(155,89,182,0.1);"><b>避凶：</b>虚招与看破加成已自动应用。<br>技能、伤残、死亡检定 +${bonus}，请在检定时手动输入加值。</div></div>`
});

const eff = thisItem.effects.getName("阵").toObject();
delete eff._id;
eff.origin = thisItem.uuid;
const lvl = Math.max(1, move.computedLevel || 1);
eff.duration = { rounds: 1 + (lvl - 1) };
eff.changes[0].value = String(1 + (lvl - 1) * 3);
await game.xjzl.api.effects.addEffect(args.target, eff);
ChatMessage.create({
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #3498db; background:rgba(52,152,219,0.1);"><b>阵：</b>速度加成已应用。<br>移动时不会被《趁虚而入》，请手动处理。</div></div>`
});

if (args.isHit) {
    const lvl = Math.max(1, move.computedLevel || 1);
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #e67e22; background:rgba(230,126,34,0.1);"><b>击飞：</b>将 ${args.target.name} 击飞 3 米！</div></div>`
    });
    await game.xjzl.api.effects.addEffect(args.target, { id: "blind", duration: { rounds: 1 + (lvl - 1) } });
}

if (args.isBroken) {
    const eff = thisItem.effects.getName("生克煎熬").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #c0392b; background:rgba(192,57,43,0.1);"><b>生克煎熬：</b>${args.target.name} 陷入生克煎熬。<br>每次出招前需手动投掷 D20，奇数外功，偶数内功，并在配置弹窗中手动切换伤害类型！</div></div>`
    });
}

// hit_once 上下文无 baseAmount，且 Buff 的 totalHealAmount 恒为 0；
// 改读首个目标的 baseAmount（本招为单体，即护体强度）
const amt = args.targets?.[0]?.baseAmount ?? 0;
if (amt > 0) {
    await actor.applyHealing({ healer: actor, amount: amt, type: "huti", showScrolling: true });
}

const hpCost = Math.floor(S.resources.hp.max * 0.5);
const mpCost = Math.floor(S.resources.mp.max * 0.5);
args.costConfig.hp = hpCost;
args.costConfig.mp = mpCost;

const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "九印合一" },
    content: `<p>是否在本场战斗中，已经完整施展过【临、兵、斗、者、皆、阵、列、前、行】前九招？</p>`,
    yes: { label: "是 (增加巨额伤害)" },
    no: { label: "否" }
});

if (confirm) {
    const hpUsed = args.costConsumed.hp;
    const mpUsed = args.costConsumed.mp;
    const bonus = Math.floor((hpUsed + mpUsed) / 2);

    args.flags.damageResult.damage += bonus;
    args.flags.damageResult.breakdown += `\n+ 九印共鸣: ${bonus} (消耗气血+内力的一半)`;

    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="margin-left:6px;"><div style="padding:5px; border-left:3px solid #ff4500; background:rgba(255,69,0,0.1);"><b>九字真言，天地无匹！</b><br>触发完美连招，额外附加 ${bonus} 点伤害！</div></div>`
    });
}

if (args.isHit) {
    const eff = thisItem.effects.getName("引燃").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);
}
